ALTER TABLE "PharmacyRequest" ADD COLUMN "originWarehouseId" TEXT REFERENCES "Warehouse"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PharmacyRequest" ADD COLUMN "idempotencyKey" TEXT UNIQUE;
ALTER TABLE "HealthStockTransferItem" ADD COLUMN "pharmacyRequestItemId" TEXT REFERENCES "PharmacyRequestItem"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "PharmacyRequestFulfillment" (id TEXT PRIMARY KEY,"requestItemId" TEXT NOT NULL REFERENCES "PharmacyRequestItem"(id) ON DELETE RESTRICT ON UPDATE CASCADE,quantity DOUBLE PRECISION NOT NULL,"movementId" TEXT NOT NULL UNIQUE REFERENCES "MaterialMovement"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"dispensationId" TEXT UNIQUE REFERENCES "MedicineDispensation"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"transferItemId" TEXT UNIQUE REFERENCES "HealthStockTransferItem"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"receiverPersonId" TEXT REFERENCES "Person"(id) ON DELETE RESTRICT ON UPDATE CASCADE,status TEXT NOT NULL DEFAULT 'ACTIVE',reason TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"cancelledAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PharmacyRequestEvent" (id TEXT PRIMARY KEY,"requestId" TEXT NOT NULL REFERENCES "PharmacyRequest"(id) ON DELETE RESTRICT ON UPDATE CASCADE,status TEXT NOT NULL,reason TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
